import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { defineConfig } from 'vite'

// 与 vite.config.core.js 唯一区别：minify 开启、只出 UMD、文件名带 .min
// 版本号同样从 package.json 注入，保证 KEditor.version 与包版本一致
const pkg = JSON.parse(readFileSync(resolve(import.meta.dirname, 'package.json'), 'utf8'))

export default defineConfig({
  define: { __KEDITOR_VERSION__: JSON.stringify(pkg.version) },
  build: {
    lib: {
      entry: resolve(import.meta.dirname, 'src/index.js'),
      name: 'KEditor',
      formats: ['umd'],
      fileName: () => 'keditor.umd.min.js',
    },
    rollupOptions: {
      output: { exports: 'named' },
    },
    outDir: 'dist',
    // core/vue 产物已先落盘，这里不能清空目录
    emptyOutDir: false,
    sourcemap: false,
    minify: 'esbuild',
    cssCodeSplit: false,
  },
})
